package android.animation;public class ValueAnimator extends Animator {public boolean started,cancelled;public int starts,removes,updateRemoves;public Runnable instant,ending; public int ends;public boolean isStarted(){return started;}public void start(){started=true;starts++;if(instant!=null)instant.run();}public void end(){ends++;started=false;if(ending!=null)ending.run();}public void cancel(){cancelled=true;started=false;}public void removeAllUpdateListeners(){updateRemoves++;}public void removeAllListeners(){removes++;}}